"use strict";(globalThis.webpackChunkgrc||=[]).push([[69978],{53090(e){e.exports=JSON.parse('{"citeKey":"tang2024dayu","slug":"tang-2024-dayu-f286","title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","type":"Conference","entryType":"inproceedings","date":"September, 2024","year":2024,"era":"iit","month":9,"doi":"10.1109/cluster59578.2024.00038","abstract":"The combination of ever-growing scientific datasets and distributed workflow complexity creates I/O performance bottlenecks due to data volume, velocity, and variety. Although the increasing use of descriptive data formats (e.g., HDF5, netCDF) helps organize these datasets, it also introduces obscure bottlenecks due to the need to translate high-level operations into file addresses and then into low-level I/O operations. To address this challenge, we introduce DaYu, a method and toolset for analyzing (a) semantic relationships between logical datasets and file addresses, (b) how dataset operations translate into I/O, and (c) the combination across entire workflows. DaYu\'s analysis and visualization enable the identification of critical bottlenecks and the reasoning about remediation. We describe our methodology and propose optimization guidelines. Evaluation on scientific workflows demonstrates up to a 3.7x performance improvement in I/O time for obscure bottlenecks. The time and storage overhead for DaYu\'s time-ordered data are typically under 0.2% of runtime and 0.25% of data volume, respectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/tang-2024-dayu-f286.pdf"},"tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"_projectIds":["portus","chronolog","labios"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["labios","chronolog","portus"],"memberAuthors":["tang-meng","cernuda-jaime","ye-jie","guo-luanzheng","tallent-nathan","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"NSF","award":"OAC-2313154","projectId":"labios"}]}')}}]);